async function api(url,{method='GET',body,courseId=course?.id,businessVersion=course?.businessVersion||selectedBusiness}={}){const r=await fetch(url,{method,headers:{'content-type':'application/json',...(learnerPreview()?{'x-learning-view':'learner'}:{}),...(businessVersion?{'x-business-version':businessVersion}:{}),...(/^\/api\/(course|course-links|images|notes|note|events|questions|question|annotations|check|faqs)(?:[/?]|$)/.test(url)&&courseId?{'x-course-id':courseId}:{}),...(session?.csrf?{'x-csrf-token':session.csrf}:{})},body:body===undefined?undefined:JSON.stringify(body),cache:'no-store'});const text=await r.text();let data;try{data=text?JSON.parse(text):{}}catch{data={error:[502,503,504].includes(r.status)?t('服务器处理超时或暂时不可用（HTTP ','The server timed out or is temporarily unavailable (HTTP ')+r.status+t('），请稍后刷新查看结果',') — refresh later to see the result'):t('服务器返回了无法识别的响应（HTTP ','Unexpected server response (HTTP ')+r.status+')'};if(r.ok)throw Error(data.error)}if(!r.ok){if(data.code==='markdown_too_large')data.error=t('每个 Markdown 文件最大','Each Markdown file may be at most ')+(data.limit||session?.uploadLimits?.markdownBytes||1000000)/1000000+' MB';if(data.code==='storage_full')data.error=t('课堂存储已满，请联系课堂管理员','Classroom storage is full. Contact the administrator.');if(data.code==='work_busy')data.error=t('任务繁忙或操作过于频繁，请稍后重试','Too many tasks. Please try again shortly.');if(data.code==='image_upload_unsupported')data.error=t('当前不支持上传图片','Image uploads are currently unavailable');if(data.code==='image_quota_exhausted')data.error=t('图片额度已耗尽','Image upload limit reached');const e=Object.assign(Error(lang==='zh'?({'Hosting subscription expired; renew to share':'托管订阅已到期，请续费后分享','Sign in through the hosting dashboard':'请从托管服务账户控制台登录','Sharing is not permitted for this course':'此课程尚未授予您分享权限，请联系管理员','Duration exceeds course sharing limit':'时长超过该课程允许的分享上限','Security verification required':'请先完成账户安全验证','Security step expired; start again':'本次验证已过期，请重新登录','Security verification failed; please try again':'答案或密码不正确，请重试','Too many security attempts; try again in 15 minutes':'验证错误次数过多，请15分钟后重试','Security confirmation does not match':'两次输入不一致，请检查','Answer needs at least 7 English letters or 3 Chinese characters':'答案至少包含7个英文字母或3个中文汉字','Security password needs at least 8 characters':'安全密码至少8个字符','Choose or enter a security question':'请选择安全问题或填写至少3个字符的自定义问题','Set up security on your previously used device or contact an administrator':'此邮箱尚未设置安全验证，请在之前使用的设备上设置，或联系管理员核对身份','Valid email required':'请填写有效的邮箱，邮箱用于唯一识别学习账户','Invalid course code':'课程口令不正确或课程已停用','Access approval required':'当前浏览器或IP尚未获得本课程许可','Course has no published material':'此课程尚未发布教材，请稍后再试','Course changed in another tab; reload before continuing':'课程已在另一个页面切换，请刷新后再操作','Invalid administrator credentials':'管理员账户或密码不正确','Invalid instructor credentials':'讲师账户或密码不正确，或账户已停用/到期','Too many requests; try later':'请求过于频繁，请稍后重试','Invalid CSRF token':'会话已更新，请刷新页面后重试','Published version changed; reload before publishing':'发布版本已被他人更改，请刷新核对后再发布','Material changed; reload before saving':'教材草稿已被他人更改，请刷新核对后再保存','Instructor not assigned to this course':'该讲师尚未获得本课程授权','Instructor sign-in required':'请先登录有效的讲师账户','Draft-authoring permission required':'尚未获得教材草稿编撰权限','Course-publication permission required':'尚未获得该课程的正式发布权限','Course statistics permission required':'尚未获得本课程聚合统计权限','Annotation permission required':'尚未获得共享批注权限'}[data.error]||data.error||r.statusText):(data.error||r.statusText)),{status:r.status,code:data.code});if(r.status===403&&!data.code?.startsWith('image_')&&!(learnerPreview()&&url.startsWith('/api/course?'))&&((course&&!location.pathname.startsWith('/admin'))||location.pathname==='/instructor'||(location.pathname==='/admin'&&data.error==='Administrator required'))){course=null;selectedBusiness='v1';setTimeout(()=>boot(),0)}throw e}return data}
function imageComposer(textarea,options){return createImageComposer(textarea,{...options,canUpload:async()=>{const d=await api('/api/images/capability');if(!d.allowed)throw Object.assign(Error(d.reason==='image_quota_exhausted'?t('图片额度已耗尽','Image upload limit reached'):t('当前不支持上传图片','Image uploads are currently unavailable')),{code:d.reason});return true}})}
const act=fn=>async e=>{e?.preventDefault?.();try{await fn(e)}catch(err){toast((err.code?.startsWith('image_')?'':t('操作未完成：','Action failed: '))+err.message)}};
const bind=(id,fn,event)=>{const el=$(id);if(!el)return;const type=event||(el.tagName==='FORM'?'submit':'click');const authentication=type==='submit'&&['access','securityForm','adminLogin','instructorLogin','questionForm','quickQuestionForm','staffReplyForm','switchCourseForm'].includes(id);let submitting=false;el.addEventListener(type,act(async e=>{if(!authentication)return fn(e);if(submitting)return;submitting=true;el.setAttribute('aria-busy','true');const buttons=[...el.querySelectorAll('button:not([type=button]),input[type=submit]')],states=buttons.map(button=>({button,disabled:button.disabled,text:button.textContent}));for(const {button} of states){button.disabled=true;if(button.tagName==='BUTTON')button.textContent=t(['questionForm','quickQuestionForm'].includes(id)?'正在保存并请求AI答疑…':id==='switchCourseForm'?'正在切换课程…':id==='securityForm'?'正在验证并进入…':['questionForm','quickQuestionForm','staffReplyForm','switchCourseForm'].includes(id)?'正在提交…':'正在登录…',['questionForm','quickQuestionForm'].includes(id)?'Saving and asking AI…':id==='switchCourseForm'?'Switching course…':id==='securityForm'?'Verifying and opening…':['questionForm','quickQuestionForm','staffReplyForm','switchCourseForm'].includes(id)?'Submitting…':'Signing in…')}try{await fn(e)}finally{submitting=false;el.removeAttribute('aria-busy');for(const {button,disabled,text} of states){button.disabled=disabled;if(button.tagName==='BUTTON')button.textContent=text}}}))};
