function spaceNotice(){if(location.pathname!=='/admin'||!session?.hosting?.canManage)return '';const q=hostingDetails?.usage;if(!q?.limits)return '';const used=q.used;const items=['courses','images'].map(k=>{const credit=k==='courses'&&q.courseCredits;return '<div><dt>'+t(({courses:credit?'可用课程':'新增课程',images:'图片',aiTokens:'模型 Tokens'})[k],({courses:credit?'Course credits':'Courses',images:'Images',aiTokens:'Model tokens'})[k])+'</dt><dd>'+(credit?q.courseCredits.available:(used[k]||0).toLocaleString()+' / '+(q.limits[k]===null?t('不限','Unlimited'):q.limits[k].toLocaleString()))+'</dd></div>'}).join('');return '<aside class="sidebar-usage" data-hosting-usage aria-label="'+t('课堂额度','Classroom quotas')+'"><h2>'+t('课堂额度','Classroom quotas')+'</h2><dl>'+items+'<div><dt>'+t('大模型接入','Model access')+'</dt><dd>'+(q.limits.globalModel?t('平台接入 / 自有接入','Platform / own connection'):t('仅自有接入','Own connection only'))+'</dd></div>'+(q.storage?'<div><dt>'+t('内容存储','Storage')+'</dt><dd>'+(q.storage.used/1000000).toFixed(1)+' / '+q.storage.cap/1000000+' MB</dd></div>':'')+'</dl><p>'+t('图片额度由课堂共享。平台模型不承诺 token 提供量或随时可用；可配置自有接入。','Image quotas are shared. Platform model access has no promised token allocation or guaranteed availability; you can configure your own connection.')+'</p>'+(q.courseCredits?'<p>'+t('基础款每月增加5门，未用可累计。','Basic adds 5 course credits monthly; unused credits carry over.')+'</p>':'')+'</aside>'}

function header(){return '<header class="top"><div><div class="eyebrow">TEACH IN PUBLIC · LEARNING WORKSPACE</div><h1>'+esc(course?localized(course.title):(session?.classroomName||t('在线培训与问答','Online Learning & Discussion')))+'</h1><nav id="breadcrumbs" class="breadcrumbs" aria-label="'+t('面包屑导航','Breadcrumb')+'"></nav></div><div class="actions">'+(session?.user.name?'<span class="user-name small muted">'+esc(session.user.name)+'</span>':'')+(session&&!session.security&&(session.course||session.admin||session.staff)?'<button id="switchCourse">'+t('切换课程','Switch course')+'</button>':'')+(course&&session?.teacher?'<button id="switchRoleView">'+t(classroomMode==='learner'?'切换讲师界面':'切换学习者界面',classroomMode==='learner'?'Switch to instructor view':'Switch to learner view')+'</button>':'')+((session?.admin||session?.staff)&&!learnerPreview()?'<a href="/instructor">'+t('讲师工作台','Instructor workspace')+'</a>':'')+(location.pathname==='/admin'&&session?.hosting?.canManage?'<a href="'+esc(session.hosting.portalUrl)+'">'+t('托管订阅','Hosting subscription')+'</a>':'')+(session?.admin&&!learnerPreview()?'<a href="/admin">'+t('管理后台','Dashboard')+'</a>':'')+(session?.course||session?.admin||session?.staff||session?.user.email?'<button id="logout">'+t('退出','Sign out')+'</button>':'<a href="/instructor">'+t('讲师','Instructor')+'</a><a href="/admin">'+t('管理员','Administrator')+'</a>')+'</div>'+languageButton(lang,lang==='zh'?'en':'zh')+classroomLink(session?.classroomInvitation,lang)+'</header>'}
function courseHash(li,pi){return '#'+new URLSearchParams({lesson:course.material.lessons[li].id,page:course.material.lessons[li].pages[pi].id})}
function updateBreadcrumbs(){const nav=$('breadcrumbs');if(!nav)return;const items=[],add=(label,href)=>items.push({label,href});if(location.pathname==='/admin'||location.pathname==='/instructor'){const admin=location.pathname==='/admin';add(t('学习课堂','Learning classroom'),'/');add(admin?t('管理后台','Dashboard'):t('讲师工作台','Instructor workspace'),location.pathname);const active=document.querySelector(admin?'[data-admin][aria-current="page"]':'[data-instructor-view][aria-current="page"]');if(active)add(active.textContent)}else if(course&&document.querySelector('.classroom')){if((session.admin||session.staff)&&!learnerPreview())add(t('讲师工作台','Instructor workspace'),'/instructor');add(localized(course.title),courseHash(0,0));add(localized(l().title),courseHash(lessonIndex,0));add(localized(p().title))}else add(t('学习课堂','Learning classroom'));nav.innerHTML='<ol>'+items.map((x,i)=>'<li>'+(x.href&&i<items.length-1?'<a href="'+esc(x.href)+'">'+esc(x.label)+'</a>':'<span aria-current="page">'+esc(x.label)+'</span>')+'</li>').join('')+'</ol>'}
function common(){mountExternalLogin({root,session,api,t,toast});compactHeader();accountMenu({user:session?.user,identity:session.identity?{...session.identity,configureUrl:session?.hosting?.canManage?session.hosting.portalUrl:null,bind:button=>startExternalLogin({button,api,t,toast})}:null,security:{load:()=>api('/api/profile/security'),save:body=>api('/api/profile/security',{method:'PUT',body})},save:name=>api('/api/profile',{method:'PATCH',body:{name}})});updateBreadcrumbs();syncDiscussionFloating();bind('switchCourse',switchCourseDialog);bind('switchRoleView',async()=>{classroomMode=classroomMode==='learner'?'instructor':'learner';localStorage.setItem('training-role-view',classroomMode);if(classroomMode==='learner'&&panel==='speaker')panel='questions';viewVersion=null;selectedBusiness=null;tabs=[{id:'start',type:'blank',title:{zh:'演示浏览',en:'Demonstration'}}];activeTab='start';course=null;pageLoad++;questionLoad++;root.innerHTML='<div class="loading">'+t('切换视图…','Switching view…')+'</div>';await loadCourse()});setupQuickDock(!!(session?.course&&session.allowed));for(const id of ['zh','en'])bind(id,async()=>{lang=id;saveLanguage(lang);document.querySelectorAll('[data-human-message]').forEach(el=>{const q=JSON.parse(el.dataset.humanMessage);el.outerHTML=humanReplyMarkup(q)});document.documentElement.lang=lang==='zh'?'zh-CN':'en';if(session.security)renderAccountSecurity();else if(location.pathname==='/admin')await renderAdmin();else if(location.pathname==='/instructor')await renderInstructor();else if(course)renderClassroom();else if(session.security)renderAccountSecurity();else renderAccess()});bind('logout',async()=>{await api('/api/logout',{method:'POST'});noteDrafts.clear();noteImageDrafts.clear();location.href='/'})}
function acceptSession(next){const changed=session&&session.user.id!==next.user.id;if(changed){for(const timer of noteTimers.values())clearTimeout(timer);noteTimers.clear();noteDrafts.clear();noteImageDrafts.clear();replyTarget=null;tabs=[{id:'start',type:'blank',title:{zh:'演示浏览',en:'Demonstration'}}];activeTab='start';course=null;loadedCourseId=null;lastEventContext=null}session=next;return changed}
async function boot(){acceptSession(await api('/api/session'));lang=readLanguage(session.language);document.documentElement.lang=lang==='zh'?'zh-CN':'en';if(new URL(location.href).searchParams.get('identity')==='linked'&&location.pathname==='/'&&!session.security){renderAccess();await chooseIdentityCourse({root,session,api,t,esc,localized,toast});return}if(session.security)return renderAccountSecurity();if(new URL(location.href).searchParams.get('signin')==='course-admin'&&session.identity?.enabled)return session.admin?renderAdmin():renderAdminLogin();if(location.pathname==='/instructor')return session.admin||session.staff?renderInstructor():renderInstructorLogin();if(location.pathname==='/admin'){if(location.hash==='#faq')adminView='faq';if(location.hash==='#lark')adminView='lark';return session.admin?renderAdmin():renderAdminLogin()}if(session.course&&session.allowed){await loadCourse();return}renderAccess()}
function renderAccess(){root.innerHTML=header()+'<div class="auth-wrap"><section class="intro"><div class="eyebrow">READ · ASK · UNDERSTAND</div><h2>'+t('不懂的地方，<br>就在课程里问。','Something unclear?<br>Ask your course.')+'</h2><p>'+t('TeachInPublic，让课程自己讲清楚。阅读双语教材，随时向AI提问，点击引用核对课程原文；也可以记录私有笔记，与讲师继续讨论。AI答疑需课堂启用模型服务。','TeachInPublic helps your course explain itself. Read bilingual materials, ask AI, and check the original passages behind an answer. Keep private notes and continue the discussion with your instructor. AI Q&A requires a configured model service.')+'</p><div class="numbered"><strong>01</strong>'+t('读教材 · 中英文随时切换','Read · Switch between Chinese and English')+'</div><div class="numbered"><strong>02</strong>'+t('问AI · 围绕本课解释，引用可查','Ask · Course-grounded answers with citations')+'</div><div class="numbered"><strong>03</strong>'+t('有边界 · 按授权访问当前教材','Stay in scope · Authorized, current course materials')+'</div></section><section class="auth">'+(session.course?pendingMarkup():accessForm())+'</section></div>';common();bind('access',async()=>{const data=await api('/api/access',{method:'POST',body:{code:$('code').value,name:$('name').value,contact:$('contact').value,consent:$('consent').checked}});session.csrf=data.csrf;await boot()});bind('requestAccess',async()=>{await api('/api/requests',{method:'POST',body:{}});await boot()});bind('checkAccess',boot);bind('changeCourse',async()=>{await api('/api/logout',{method:'POST'});await boot()})}
function accessForm(){return '<h2>'+t('进入学习','Start learning')+'</h2><p class="small muted">'+t('课程口令不区分大小写。非白名单访客需获得批准。','Course codes are case-insensitive. Visitors outside the allowlist need approval.')+'</p><form id="access"><label>'+t('课程口令','Course code')+'<input id="code" autocomplete="off" required maxlength="100"></label><label>'+t('姓名或学习昵称','Name / learning display name')+'<input id="name" required maxlength="80" autocomplete="name" value="'+esc(session.user.name)+'"></label><label>'+t('邮箱（账户唯一标识，供审批核对）','Email (unique account ID, for approval review)')+'<input id="contact" type="email" required maxlength="200" autocomplete="email" value="'+esc(session.user.email||'')+'"></label><label class="inline"><input type="checkbox" id="consent" required><span>'+t('我知悉系统会记录访问IP、浏览页面、活跃阅读时长、滚动及问答等学习数据，用于培训统计。笔记和私有留言仅本人可见，不纳入商户的飞书/Lark同步及恢复。公共或讲师可见留言可能由课堂所有人备份至其授权云空间。','I understand that access IPs, pages, active reading time, scrolling and discussions are recorded for training analytics. Private notes and personal-only discussions are excluded from merchant Feishu/Lark sync and recovery. Public or staff-visible discussions may be backed up to the classroom owner’s authorized cloud space.')+'</span></label><button class="primary">'+t('验证口令并继续','Verify code and continue')+'</button></form>'}
function pendingMarkup(){const r=session.request,brief=session.course.brief;return '<h2>'+esc(localized(session.course.title))+'</h2>'+(brief?'<p class="muted course-brief">'+esc(lang==='zh'?brief.zh||brief.en:brief.en||brief.zh)+'</p>':'')+'<p>'+t('口令已验证，尚未获得当前网络的学习资格。','Code verified. Access from your current network is not yet approved.')+'</p><div class="message"><b>'+t('当前IP：','Current IP: ')+esc(session.ip)+'</b><br>'+t('审批与当前浏览器、课程及IP绑定，转发地址不会转移许可。','Approval is bound to this browser identity, course and IP; sharing the link does not transfer permission.')+'</div>'+(r?'<p class="small muted">'+t('申请状态：','Request status: ')+esc(statusText(r.status))+' · '+esc(r.id.slice(0,8))+'</p>':'')+'<button id="requestAccess" class="primary" '+(r?.status==='pending'?'disabled':'')+'>'+t(r?.status==='pending'?'等待审批中':'申请开始学习',r?.status==='pending'?'Awaiting approval':'Request access')+'</button><div class="actions"><button id="checkAccess">'+t('检查授权结果','Check approval')+'</button>'+'<button id="changeCourse">'+t('切换课程','Change course')+'</button></div><p class="small muted">'+t('管理员可在后台或已配置的飞书卡片批准。页面会自动检查审批结果。','An administrator can approve through the dashboard or a configured Lark card. This page checks automatically.')+'</p>'}
function renderAdminLogin(){root.innerHTML=header()+'<div class="auth-wrap"><section class="intro"><div class="eyebrow">INSTRUCTOR WORKSPACE</div><h2>'+t('组织课程，<br>看见学习过程。','Teach with context.<br>See learning activity.')+'</h2><p>'+t('审批、教材版本、问答热点和学习统计在这里统一管理。','Manage approvals, material versions, discussion hotspots and learning analytics in one place.')+'</p></section><section class="auth"><h2>'+t('管理员登录','Administrator sign-in')+'</h2><form id="adminLogin"><label>'+t('账户','Username')+'<input id="username" autocomplete="username" value="admin" required></label><label>'+t('密码','Password')+'<input type="password" id="password" autocomplete="current-password" required></label><button class="primary">'+t('登录后台','Sign in')+'</button></form><p class="small"><a href="/">'+t('返回学习入口','Back to learning')+'</a></p></section></div>';common();bind('adminLogin',async()=>{const data=await api('/api/admin/login',{method:'POST',body:{username:$('username').value,password:$('password').value}});session.csrf=data.csrf;await boot()})}
function currentRoute(){const q=new URLSearchParams(location.hash.slice(1)),lessons=course.material.lessons;const moved=lessons.findIndex(x=>x.pages.some(page=>page.id===q.get('page')));const li=moved>=0?moved:lessons.findIndex(x=>x.id===q.get('lesson'));lessonIndex=li>=0?li:Math.max(0,Math.min(lessonIndex,lessons.length-1));const pi=l().pages.findIndex(x=>x.id===q.get('page'));pageIndex=pi>=0?pi:0;if(q.get('page')&&pi<0)toast(t('该页面已不在当前修订中，已打开本讲首页；历史记录可在全部问答和全部笔记中查看。','This page is not in the selected revision. Opened the first page; historical records remain in all discussions and all notes.'))}
