let answerTrail=[],answerPosition=-1;
function dialog(content,{history=false}={}){sendEvent('pause');const modal=$('dialog'),body=$('dialogContent');if(!history||!modal.open){answerTrail=[];answerPosition=-1}if(history&&modal.open&&answerPosition>=0){answerTrail[answerPosition]={nodes:[...body.childNodes],scroll:modal.scrollTop};answerTrail.splice(answerPosition+1)}body.innerHTML=content;if(history){answerTrail.push({nodes:[...body.childNodes],scroll:0});answerPosition=answerTrail.length-1}renderAnswerNavigation();modal.showModal();modal.scrollTop=0}
function renderAnswerNavigation(){document.getElementById('answerNavigation')?.remove();if(!answerTrail.length)return;const nav=document.createElement('nav');nav.id='answerNavigation';nav.className='answer-navigation';nav.setAttribute('aria-label',t('回答浏览历史','Answer browsing history'));nav.innerHTML='<button type="button" id="answerBack">← '+t('后退','Back')+'</button><span>'+ (answerPosition+1)+' / '+answerTrail.length+'</span><button type="button" id="answerForward">'+t('前进','Forward')+' →</button>';$('dialogContent').before(nav);for(const [id,delta]of [['answerBack',-1],['answerForward',1]]){const button=$(id);button.disabled=answerPosition+delta<0||answerPosition+delta>=answerTrail.length;button.onclick=()=>{const body=$('dialogContent');answerTrail[answerPosition]={nodes:[...body.childNodes],scroll:$('dialog').scrollTop};answerPosition+=delta;body.replaceChildren(...answerTrail[answerPosition].nodes);renderAnswerNavigation();$('dialog').scrollTop=answerTrail[answerPosition].scroll}}}
$('dialog').addEventListener('close',()=>{answerTrail=[];answerPosition=-1;$('answerNavigation')?.remove();$('dialogContent').replaceChildren()});
async function withAnswerProgress(form,task){if((form.id==='questionForm'&&(replyTarget||$('threadKind').value!=='question'))||(form.id==='quickQuestionForm'&&$('quickKind').value!=='question'))return task(form);if(form.dataset.answerBusy)return;form.dataset.answerBusy='true';const buttons=[...form.querySelectorAll('button')],disabled=buttons.map(b=>b.disabled);buttons.forEach(b=>b.disabled=true);const host=document.createElement('div');form.append(host);const progress=generationProgress(host,t,{answer:true});try{return await task(form)}finally{progress.finish();host.remove();delete form.dataset.answerBusy;buttons.forEach((b,i)=>b.disabled=disabled[i])}}

function annotationDialog(){const page=p().id;dialog('<h2>'+t('添加共享教学批注','Add a shared teaching annotation')+'</h2><p class="small muted">'+t('本课程获准学员可见，两种语言须同时填写。','Visible to approved participants. Both languages are required.')+'</p><form id="annotationForm"><label>中文<textarea id="annotationZh" required maxlength="5000"></textarea></label><label>English<textarea id="annotationEn" required maxlength="5000"></textarea></label><button class="primary">'+t('发布批注','Publish annotation')+'</button></form>');bind('annotationForm',async()=>{await api('/api/annotations',{method:'POST',body:{page,body:{zh:$('annotationZh').value,en:$('annotationEn').value}}});$('dialog').close();await loadAnnotations()})}
function pinPage(){sendEvent('pause');readingPane='browser';if(tabs.length>=8)return toast(t('最多8个演示标签，请先关闭一个。','Close a tab before adding another (maximum 8).'));const page=p();const tab={id:'tab-'+(++tabSequence),type:'material',title:page.title,page:structuredClone(page),version:course.version};tabs.push(tab);activeTab=tab.id;browserOpen=true;$('browserPanel').hidden=false;setLessonToolLabel($('browserToggle'),t('隐藏对照','Hide workspace'));renderBrowser()}
function renderBrowser(){const el=$('browserPanel');if(!el)return;parkStudyPanel();const tab=tabs.find(x=>x.id===activeTab)||tabs[0];activeTab=tab.id;const home=courseLinks.find(x=>!x.page_id);el.innerHTML='<div class="workspace-tools">'+(home?'<div class="browser-home-toolbar"><button id="browserHome" title="'+esc(home.url)+'">⌂ '+t('课程主页','Course home')+'</button></div>':'')+'<nav class="browser-tabs" role="tablist" aria-label="Presentation workspace">'+tabs.map(x=>'<button role="tab" data-tab="'+x.id+'" aria-selected="'+(x.id===activeTab)+'">'+esc(localized(x.title))+'</button><button data-close-tab="'+x.id+'" aria-label="'+t('关闭标签','Close tab')+'">×</button>').join('')+'<button id="openStudyWorkspace">'+t('笔记与问答','Notes & discussion')+'</button><button id="addBrowser" aria-label="'+t('添加浏览标签','Add browser tab')+'">＋</button><button id="maximizeBrowser">'+t('放大/还原','Expand/restore')+'</button><button id="closeBrowser">'+t('隐藏','Hide')+'</button></nav>'+(['material','study'].includes(tab.type)?'':'<form id="browserAddress" class="browser-address"><input id="browserUrl" type="text" inputmode="url" placeholder="https://…" aria-label="URL" value="'+esc(tab.url||'https://')+'" required><button>'+t('打开','Open')+'</button>'+(tab.url?'<a href="'+esc(tab.url)+'" target="_blank" rel="noopener noreferrer" aria-label="'+t('在新窗口打开','Open in new window')+'">↗</a>':'')+'</form>')+'</div><div id="browserBody" class="browser-body">'+(tab.type==='study'?'':tab.type==='material'?'<div class="markdown"><span class="badge">'+t('演示快照','Presentation snapshot')+' · R'+tab.version+'</span><h2>'+esc(localized(tab.page.title))+'</h2>'+markdown(localized(tab.page.body))+'</div>':tab.url?'<iframe title="'+t('演示浏览','Demonstration browser')+'" src="'+esc(tab.url)+'" sandbox="allow-scripts allow-forms allow-same-origin allow-popups" referrerpolicy="no-referrer"></iframe>':'<div class="empty-state"><div class="eyebrow">PRESENTATION WORKSPACE</div><h2>'+t('右侧，多页对照。','More room for context.')+'</h2><p>'+t('输入业务系统地址，或点击左侧“本页放到右侧”放大展示教材。标签独立保留，可边讲边切换。','Open a business system above, or present a lesson page here. Independent tabs retain your comparisons while the lesson continues.')+'</p><p class="small">'+t('若外部系统禁止嵌入，请使用新窗口并排展示。','If an external system blocks embedding, open it in a separate window.')+'</p></div>')+'</div>';
 for(const [id,icon] of [['browserHome','⌂'],['openStudyWorkspace','☷'],['maximizeBrowser','⛶'],['closeBrowser','×']]){const button=$(id);if(button){const label=button.textContent;button.title=label;button.setAttribute('aria-label',label);button.textContent=icon}}placeStudyPanel();bind('openStudyWorkspace',openStudyWorkspace);bind('browserHome',()=>{const existing=tabs.find(x=>x.type==='url'&&x.url===home.url);if(existing){sendEvent('pause');activeTab=existing.id;readingPane='browser';renderBrowser()}else openSystemTab(home.title,home.url)});el.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{sendEvent('pause');activeTab=b.dataset.tab;readingPane='browser';renderBrowser();sendEvent('view')});el.querySelectorAll('[data-close-tab]').forEach(b=>b.onclick=()=>{tabs=tabs.filter(x=>x.id!==b.dataset.closeTab);if(!tabs.length)tabs=[{id:'start',type:'blank',title:{zh:'演示浏览',en:'Demonstration'}}];if(!tabs.some(x=>x.id===activeTab))activeTab=tabs[0].id;renderBrowser()});bind('addBrowser',()=>{if(tabs.length>=8)return;const x={id:'tab-'+(++tabSequence),type:'blank',title:{zh:'新浏览页',en:'Browser tab'}};tabs.push(x);activeTab=x.id;renderBrowser()});bind('maximizeBrowser',()=>{sendEvent('pause');el.classList.toggle('maximized');readingPane=el.classList.contains('maximized')?'browser':'reader';sendEvent('view')});bind('closeBrowser',()=>{sendEvent('pause');browserOpen=false;el.hidden=true;readingPane='reader';sendEvent('view')});bind('browserAddress',()=>{let url;try{const entered=$('browserUrl').value.trim();url=new URL(/^[a-z][a-z0-9+.-]*:/i.test(entered)?entered:'https://'+entered);if(url.protocol!=='https:'||url.username||url.password||url.origin===location.origin)throw Error()}catch{return toast(t('请使用不含密码的外部HTTPS地址。','Use an external HTTPS URL without embedded credentials.'))}sendEvent('pause');tab.type='url';readingPane='browser';tab.url=url.href;tab.title={zh:url.hostname,en:url.hostname};renderBrowser()})}
