async function renderRequests(){const data=await api('/api/admin/requests?'+accessQuery('requests'));if(adminView!=='requests')return;$('adminMain').innerHTML='<h1>'+t('访问审批','Access requests')+'</h1><p class="muted">'+t('批准绑定当前浏览器、课程及IP。仅批准本人不会让同IP所有人自动进入；批准IP则该出口的其他访客也可通过课程口令进入。','Approval binds the browser identity, course and IP. Approving a person does not admit everyone at that IP; an IP allowlist entry does.')+'</p><p class="small muted">'+t('访问和有效学习时长统计最近7天；剩余授权时长按当前许可计算。','Visits and active learning time cover the last 7 days; remaining access reflects the current grant.')+'</p>'+accessControls('requests',t)+'<button id="requestsRefresh">'+t('刷新申请','Refresh requests')+'</button><section class="card">'+(data.length?data.map(r=>'<div class="request"><div><b>'+esc(r.name)+'</b> <span class="badge '+(r.status==='approved'?'ok':r.status==='pending'?'warn':'')+'">'+esc(r.status)+'</span><p>'+esc(r.contact)+' · '+esc(r.course_id)+' · '+esc(r.ip)+'</p>'+accessMetrics(r,t)+'<p class="small muted">'+timestamp(r.created)+' · '+esc(r.id.slice(0,8))+(r.expires?' · '+t('到期 ','Expires ')+(r.clockMode==='first-open'?r.durationHours+t('小时，从首次阅读起',' hours from first reading'):timestamp(r.expires)):'')+'</p></div><div class="actions">'+(r.status==='pending'?'<input type="number" id="hours-'+r.id+'" value="168" min="1" max="2160" aria-label="Hours" class="hours-input"><span class="small">'+t('小时','hours')+'</span><button class="primary" data-approve="'+r.id+'">'+t('批准本人','Approve person')+'</button><button data-approve-ip="'+r.id+'">'+t('批准IP','Allow IP')+'</button><button class="danger" data-deny="'+r.id+'">'+t('拒绝','Deny')+'</button>':'<input type="number" id="hours-'+r.id+'" value="168" min="1" max="2160" aria-label="'+t('从本次保存起的小时数','Hours from this save')+'" class="hours-input"><span class="small">'+t('小时，从本次保存起','hours from this save')+'</span><button data-approve="'+r.id+'">'+t(r.status==='approved'?'调整授权时长':'重新授权',r.status==='approved'?'Adjust access duration':'Reauthorize')+'</button>'+(r.status==='approved'?'<button class="danger" data-revoke="'+r.id+'">'+t('撤销个人许可','Revoke personal grant')+'</button>':''))+'</div></div>').join(''):'<p class="muted">'+t('暂无申请。','No requests.')+'</p>')+'</section><p class="small muted">'+t('个人许可撤销不会删除独立IP白名单；如要停止该IP全部访问，请同时移除白名单。','Revoking a personal grant does not remove an independent IP allowlist entry. Remove the allowlist entry as well to block that network.')+'</p>';
 bindAccessControls('requests',act(renderRequests));bind('requestsRefresh',renderRequests);for(const [attr,status,whitelist]of [['approve','approved',false],['approve-ip','approved',true],['deny','denied',false]])document.querySelectorAll('[data-'+attr+']').forEach(b=>b.onclick=act(async()=>{if(whitelist&&!await webConfirm(t('这会允许该IP的其他访客使用课程口令进入，继续？','This admits other visitors at this IP with the course code. Continue?')))return;const id=b.getAttribute('data-'+attr);await api('/api/admin/requests',{method:'POST',body:{id,status,hours:Number($('hours-'+id).value),whitelist}});await renderRequests()}));document.querySelectorAll('[data-revoke]').forEach(b=>b.onclick=act(async()=>{await api('/api/admin/revoke',{method:'POST',body:{id:b.dataset.revoke}});await renderRequests()}))}
