 bind('saveAI',async()=>{await api('/api/admin/ai',{method:'PUT',body:{baseURL:$('aiURL').value,model:$('aiModel').value,key:$('aiKey').value}});$('aiKey').value='';toast(t('已保存','Saved'))});
 bind('convertAI',async()=>{const file=$('aiFile').files[0];if(!file)throw Error(t('请选择一个附件','Select one attachment'));const max=session?.uploadLimits?.markdownBytes||1000000;if(file.size>max)throw Error(t('附件大小上限：','Attachment limit: ')+max/1000000+' MB');const button=$('convertAI');button.disabled=true;const progress=generationProgress($('aiCapacityNotice'),t);try{const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file)});progress.update('generating');generated=await api('/api/admin/ai/convert',{method:'POST',body:{source:$('aiSource').value,file:{name:file.name,data}}});$('aiZh').value=generated.files[0].markdown;$('aiEn').value=generated.files[1].markdown;$('aiPreview').hidden=false;progress.finish(generated.modelAccess?.message||'');toast(t('生成成功，请审核双语内容','Generated. Review both languages.'))}catch(e){progress.finish(e.message);throw e}finally{button.disabled=false}});
