let quickDockBound=false,quickDockDragging=false,quickDockSuppressUntil=0;
function quickDockBounds(){const viewport=visualViewport,w=viewport?.width||innerWidth,h=viewport?.height||innerHeight,x=viewport?.offsetLeft||0,y=viewport?.offsetTop||0,header=document.querySelector('#app>.top')?.getBoundingClientRect(),toolbar=document.querySelector('.reader>.toolbar')?.getBoundingClientRect(),footer=document.querySelector('.page-nav')?.getBoundingClientRect();const bottom=Math.max(y+8,Math.min(y+h-60,footer?.height?footer.top-56:y+h-84)),top=Math.min(bottom,Math.max(y+12,header?.height?header.bottom+8:y+12,toolbar?.height?toolbar.bottom+8:y+12));return {x,w,top,bottom}}
