async function renderPptShares(){const data=await api('/api/admin/ppt-shares?offset='+pptAdminOffset);$('adminMain').innerHTML='<section class="card"><h2>'+t('PPT 分享与延期','PPT shares & extensions')+'</h2><p>'+t('同一链接的延期申请合并为一行，每天最多受理一次（北京时间）。新建、调整及延期遵循课程时长上限（默认24小时，最多7天）；撤销立即停止新访问，已打开页面最迟30秒检查一次撤销状态。','Extension requests merge into one row per link, at most once per day (Asia/Shanghai). Creation, adjustments and extensions follow the course limit (24 hours by default; up to 7 days). Revocation blocks new access immediately; open readers check at least every 30 seconds while visible.')+'</p><button id="refreshPptShares">'+t('刷新','Refresh')+'</button>'+table([t('课程 / 修订','Course / revision'),t('创建者','Creator'),t('期限与状态','Validity / state'),t('延期申请','Extension request'),t('处理','Actions')],data.items.map(r=>[esc(r.course_id)+' · '+esc(r.business_id)+' · R'+r.revision,esc(r.creator_name)+'<br>'+esc(r.creator_email),(r.clockMode==='first-open'?r.durationHours+t('小时，从首次阅读起',' hours from first reading'):timestamp(r.expires))+'<br>'+t(r.preapproved?'整条链接已预批准':'逐个访客审批',r.preapproved?'Entire link preapproved':'Individual approval')+'<br>'+t(r.revoked?'已撤销':Date.parse(r.expires)<=Date.now()?'已过期':'有效',r.revoked?'Revoked':Date.parse(r.expires)<=Date.now()?'Expired':'Active'),r.request_status?esc(({pending:t('待审核','Pending'),approved:t('已批准','Approved'),denied:t('已拒绝','Denied'),revoked:t('已撤销','Revoked')})[r.request_status]||r.request_status)+'<br>'+t('首次：','First: ')+timestamp(r.first_request)+'<br>'+t('最近：','Latest: ')+timestamp(r.last_request)+'<br>'+t('受理天数：','Accepted days: ')+r.request_days:'—',r.revoked?'<div class="actions"><input id="pptRestoreHours-'+r.id+'" type="number" min="1" max="'+r.maxHours+'" value="'+Math.min(r.durationHours||24,r.maxHours)+'" aria-label="'+t('重新授权时长（小时）','Reauthorization hours')+'"><button data-ppt-restore="'+r.id+'">'+t('重新授权链接','Reauthorize link')+'</button></div>':'<div class="actions"><input id="pptDuration-'+r.id+'" type="number" min="1" max="'+r.maxHours+'" value="'+Math.min(24,r.maxHours)+'" aria-label="'+t('从处理时起的小时数','Hours from approval')+'" style="width:85px"><button data-ppt-time="'+r.id+'">'+t('调整时长','Set duration')+'</button><button data-ppt-pre="'+r.id+'" data-enabled="'+(!r.preapproved)+'">'+t(r.preapproved?'取消整条预批准':'提前批准整条链接',r.preapproved?'Cancel link preapproval':'Preapprove entire link')+'</button>'+ (r.request_status==='pending'?'<input type="number" id="pptHours-'+r.id+'" min="1" max="'+r.maxHours+'" value="'+Math.min(24,r.maxHours)+'" aria-label="Extension hours" style="width:85px"><button data-ppt-approve="'+r.id+'">'+t('批准延期','Approve extension')+'</button><button data-ppt-deny="'+r.id+'">'+t('拒绝','Deny')+'</button>':'')+'<button class="danger" data-ppt-revoke="'+r.id+'">'+t('撤销链接','Revoke link')+'</button></div>']))+'<div class="actions"><button id="pptAdminPrev" '+(!pptAdminOffset?'disabled':'')+'>'+t('上一组','Previous')+'</button><span>'+data.total+'</span><button id="pptAdminNext" '+(pptAdminOffset+30>=data.total?'disabled':'')+'>'+t('下一组','Next')+'</button></div></section>';$('adminMain').insertAdjacentHTML('afterbegin','<section id="pptVisitors" class="card"></section>');await renderPptVisitors();await renderPptPolicy();document.querySelectorAll('[data-ppt-time],[data-ppt-pre]').forEach(b=>b.onclick=act(async()=>{const id=b.dataset.pptTime||b.dataset.pptPre,pre=b.dataset.enabled==='true',body={id,hours:Number($('pptDuration-'+id).value)};if(b.dataset.pptPre){if(pre&&!await webConfirm(t('批准整条链接后，持有链接的访客无需逐个等待审批即可阅读。确认？','Preapprove this entire link? Anyone holding it may read without individual approval.')))return;body.preapproved=pre;if(!pre)delete body.hours}const result=await api('/api/admin/ppt-shares/manage',{method:'POST',body});toast(result.clockMode==='first-open'?t('首次获准阅读后有效小时数：','Hours from first approved reading: ')+result.durationHours:t('有效期已更新至：','Valid until: ')+timestamp(result.expires));await renderPptShares()}));document.querySelectorAll('[data-ppt-restore]').forEach(b=>b.onclick=act(async()=>{if(!await webConfirm(t('恢复此链接并重新计时？原先逐人撤销的授权不会恢复。','Restore this link and restart reading windows? Individually revoked visitors stay revoked.')))return;await api('/api/admin/ppt-shares/manage',{method:'POST',body:{id:b.dataset.pptRestore,restore:true,hours:Number($('pptRestoreHours-'+b.dataset.pptRestore).value)}});await renderPptShares()}));bind('refreshPptShares',renderPptShares);bind('pptAdminPrev',()=>{pptAdminOffset=Math.max(0,pptAdminOffset-30);return renderPptShares()});bind('pptAdminNext',()=>{pptAdminOffset+=30;return renderPptShares()});for(const action of ['approve','deny','revoke'])document.querySelectorAll('[data-ppt-'+action+']').forEach(b=>b.onclick=act(async()=>{const id=b.getAttribute('data-ppt-'+action);if(!await webConfirm(t('确认处理此分享链接？','Confirm this share action?')))return;if(action==='revoke')await api('/api/ppt-shares',{method:'DELETE',body:{id}});else await api('/api/admin/ppt-shares/decision',{method:'POST',body:{id,decision:action,hours:Number($('pptHours-'+id).value)}});await renderPptShares()}))}
let pptVisitorOffset=0;
async function renderPptVisitors(){const d=await api('/api/admin/ppt-visitors?'+accessQuery('visitors')+'&offset='+pptVisitorOffset);$('pptVisitors').innerHTML='<h2>'+t('分享访客授权','Shared reading approvals')+'</h2><p>'+t('重新授权从下次阅读起计时；调整已授权时长以原开始时间计算，仅影响此访客。同一链接、同一邮箱沿用同一阅读期限。','Reauthorization starts at the next reading; duration adjustments retain the original start time and affect only this visitor. The same email on the same link shares one reading window.')+'</p><p class="small muted">'+t('访问与学习统计为最近90天，同一链接和邮箱汇总；剩余时长以当前授权为准。','Visits and learning cover the last 90 days, grouped by link and email; remaining time reflects current authorization.')+'</p>'+accessControls('visitors',t)+table([t('访客','Visitor'),t('分享创建者','Sharer'),t('课程 / 状态','Course / status'),t('处理','Actions')],d.items.map(r=>[esc(r.name)+'<br>'+esc(r.email)+'<br>'+esc(r.ip),esc(r.creator_name)+'<br>'+esc(r.creator_email),esc(r.course_id)+'<br>'+esc(statusText(r.status))+'<br>'+(r.durationHours?r.durationHours+t('小时',' hours'):'')+'<br>'+(r.expires?timestamp(r.expires):t('首次阅读后开始计时','Starts on first reading'))+accessMetrics(r,t),'<label>'+t('此访客时长（小时）','Visitor duration (hours)')+'<input id="visitorHours-'+r.id+'" type="number" min="1" max="'+r.maxHours+'" value="'+Math.min(r.durationHours||24,r.maxHours)+'"></label>'+(r.share_revoked?'<p>'+t('请先重新授权分享链接','Reauthorize the share link first')+'</p>':(r.status==='approved'?['adjust','revoke']:['approve','deny']).map(a=>'<button data-visitor="'+r.id+'" data-decision="'+a+'">'+({approve:t(r.status==='revoked'||r.status==='denied'?'重新授权':'批准',r.status==='revoked'||r.status==='denied'?'Reauthorize':'Approve'),adjust:t('保存时长','Save duration'),deny:t('拒绝','Deny'),revoke:t('撤销授权','Revoke')})[a]+'</button>').join(' '))]));$('pptVisitors').insertAdjacentHTML('beforeend','<div class="actions"><button id="visPrev" '+(!pptVisitorOffset?'disabled':'')+'>'+t('上一组','Previous')+'</button><span>'+d.total+'</span><button id="visNext" '+(pptVisitorOffset+30>=d.total?'disabled':'')+'>'+t('下一组','Next')+'</button></div>');bindAccessControls('visitors',act(()=>{pptVisitorOffset=0;return renderPptVisitors()}));bind('visPrev',()=>{pptVisitorOffset=Math.max(0,pptVisitorOffset-30);return renderPptVisitors()});bind('visNext',()=>{pptVisitorOffset+=30;return renderPptVisitors()});document.querySelectorAll('[data-visitor]').forEach(b=>b.onclick=act(async()=>{await api('/api/admin/ppt-visitors/decision',{method:'POST',body:{id:b.dataset.visitor,decision:b.dataset.decision,...(['approve','adjust'].includes(b.dataset.decision)?{hours:Number($('visitorHours-'+b.dataset.visitor).value)}:{})}});await renderPptShares()}))}

async function renderPptPolicy(){
 if(!$('pptPolicy'))$('adminMain').insertAdjacentHTML('afterbegin','<section id="pptPolicy" class="card"></section>');
 const selected=adminCourses.some(c=>c.id===adminCourse)?adminCourse:adminCourses[0]?.id;if(!selected)return;
 const d=await api('/api/admin/ppt-policy?course='+encodeURIComponent(selected));
 $('pptPolicy').innerHTML='<h2>'+t('课程分享权限与时长','Course sharing permissions and duration')+'</h2><label>'+t('课程','Course')+'<select id="sharePolicyCourse">'+adminCourses.map(c=>'<option value="'+esc(c.id)+'" '+(c.id===selected?'selected':'')+'>'+esc(localized(c.title))+'</option>').join('')+'</select></label><form id="sharePolicyForm"><label>'+t('进入课程默认模式','Default course entry mode')+'<select id="entryMode"><option value="classroom" '+(d.entryMode!=='ppt'?'selected':'')+'>'+t('课堂模式','Classroom')+'</option><option value="ppt" '+(d.entryMode==='ppt'?'selected':'')+'>PPT</option></select></label><label class="inline"><input id="shareAllowAll" type="checkbox" '+(d.allowAll?'checked':'')+'><span>'+t('默认允许本课程已获授权的用户分享','Allow authorized course users to share by default')+'</span></label><label>'+t('最长分享时长（小时，1–168；默认24）','Maximum sharing duration (hours, 1–168; default 24)')+'<input id="shareMaxHours" type="number" min="1" max="168" required value="'+d.maxHours+'"></label><button class="primary">'+t('保存课程设置','Save course settings')+'</button></form><p>'+t('管理员可创建分享；普通用户和讲师遵循课程默认值或邮箱单独授权。时长上限对所有新建、调整及延期生效；已有链接截止时间不自动改变。','Administrators may create shares. Learners and instructors follow the course default or email override. Duration limits apply to creation, adjustments and extensions; existing expiry times are unchanged.')+'</p><form id="shareGrantForm" class="filters"><label>Email<input id="shareGrantEmail" type="email" required maxlength="200"></label><label>'+t('单独授权','Override')+'<select id="shareGrantAllowed"><option value="true">'+t('允许分享','Allow sharing')+'</option><option value="false">'+t('禁止分享','Deny sharing')+'</option><option value="inherit">'+t('恢复课程默认','Use course default')+'</option></select></label><button>'+t('保存用户授权','Save user permission')+'</button></form>'+table(['Email',t('权限','Permission')],d.grants.map(g=>[esc(g.email),g.allowed?t('允许分享','Allowed'):t('禁止分享','Denied')]));
 bind('sharePolicyCourse',async()=>{adminCourse=$('sharePolicyCourse').value;await renderPptPolicy()},'change');
 bind('sharePolicyForm',async()=>{await api('/api/admin/ppt-policy',{method:'PUT',body:{course:selected,entryMode:$('entryMode').value,allowAll:$('shareAllowAll').checked,maxHours:Number($('shareMaxHours').value)}});await renderPptShares()});
 bind('shareGrantForm',async()=>{const value=$('shareGrantAllowed').value;await api('/api/admin/ppt-grant',{method:'PUT',body:{course:selected,email:$('shareGrantEmail').value,allowed:value==='inherit'?null:value==='true'}});await renderPptPolicy()})
}

document.addEventListener('click',async event=>{const button=event.target.closest('[data-knowledge-source]');if(!button)return;try{const source=await api('/api/knowledge/source?'+new URLSearchParams({id:button.dataset.knowledgeSource,businessVersion:button.dataset.business}));if(!button.isConnected)return;if(!$('dialog').open){const answer=button.closest('.ai-answer');if(answer)dialog('<h2>'+t('AI课程答疑','AI course answer')+'</h2>'+answer.outerHTML,{history:true})}dialog('<h2>'+esc(source.title)+'</h2><p>'+esc(source.section)+'</p><div class="knowledge-evidence message-markdown">'+markdown(source.text)+'</div><p>'+t('仅展示当前有效授权的原文片段。','Only currently authorized source passages are shown.')+'</p>',{history:true})}catch(e){toast(e.message)}});

document.addEventListener('click',event=>{const button=event.target.closest('[data-ai-translation]');if(button)button.closest('.ai-answer').querySelector('.text').innerHTML=markdown(button.dataset.aiTranslation)});

function humanReplyMarkup(q,selected=lang){
 if(q.removed||!q.body?.trim())return esc(q.body||'');
 const original=q.language||(/[\p{Script=Han}]/u.test(q.body)?'zh':'en'),translations=q.translations||{},translated=selected!=='original'&&!!translations[selected],text=translated?translations[selected]:q.body;
 const payload={id:q.id,course_id:q.course_id,businessVersion:q.businessVersion,body:q.body,language:original,translations,mine:q.mine,kind:q.kind,author_edited_at:q.author_edited_at};
 return '<div data-human-message="'+esc(JSON.stringify(payload))+'"><div class="human-message-text message-markdown">'+markdown(text)+'</div><span class="actions small"><button type="button" data-human-language="original">'+t('原文','Original')+'</button>'+['zh','en'].map(code=>'<button type="button" data-human-language="'+code+'" title="'+(translations[code]||code===original?t('显示已保存内容，无需再次翻译','Show saved text without another translation'):t('使用课堂模型翻译并保存','Translate and save using the classroom model'))+'">'+(translations[code]||code===original?'':'译 ')+(code==='zh'?'中文':'English')+'</button>').join('')+'<span class="muted">'+(translated?t('机器翻译 · 原文保留','Machine translation · original retained'):'')+'</span>'+(q.mine?'<button type="button" data-edit-own>'+t('编辑','Edit')+'</button>':'')+(q.author_edited_at?'<span class="muted">'+t('作者已修改','Edited by author')+'</span>':'')+'</span></div>';
}
document.addEventListener('click',async event=>{
 const button=event.target.closest('[data-human-language]');if(!button)return;
 const host=button.closest('[data-human-message]'),q=JSON.parse(host.dataset.humanMessage),target=button.dataset.humanLanguage;
 if(target==='original'||q.translations?.[target]||target===q.language){host.outerHTML=humanReplyMarkup(q,target);return}
 const buttons=host.querySelectorAll('button');buttons.forEach(b=>b.disabled=true);button.textContent=t('翻译中…','Translating…');
 try{const data=await api('/api/question/translate',{method:'POST',body:{id:q.id,language:target},courseId:q.course_id,businessVersion:q.businessVersion});q.translations=data.translations;for(const el of document.querySelectorAll('[data-human-message]')){const other=JSON.parse(el.dataset.humanMessage);if(other.id===q.id&&other.body===q.body)el.outerHTML=humanReplyMarkup({...other,translations:data.translations},el===host?target:lang)}}
 catch(e){toast(t('翻译未完成，原文已保留。','Translation could not finish; the original is preserved.')+' '+e.message);if(host.isConnected)host.outerHTML=humanReplyMarkup(q)}
});

document.addEventListener('click',event=>{const button=event.target.closest('[data-edit-own]');if(!button)return;const q=JSON.parse(button.closest('[data-human-message]').dataset.humanMessage);if(!q.mine)return;
 dialog('<h2>'+t('编辑提问或回复','Edit question or reply')+'</h2><form id="editOwnMessage"><label>'+t('内容','Message')+'<textarea id="editOwnText" required maxlength="4000">'+esc(q.body)+'</textarea></label><p class="small muted">'+t('保留原有回复和附件。修改后旧AI回答与译文失效。','Existing replies and attachments are retained. Editing invalidates the previous AI answer and translation.')+'</p><div class="actions"><button type="submit" class="primary" value="save">'+t('保存修改','Save changes')+'</button>'+(!q.kind||q.kind==='question'?'<button type="submit" value="regenerate">'+t('保存并重新生成回答','Save & regenerate answer')+'</button>':'')+'</div><p id="editOwnError" role="status"></p></form>');
 $('editOwnMessage').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget;if(form.dataset.answerBusy)return;const text=form.querySelector('textarea').value,regenerate=e.submitter?.value==='regenerate',controls=[...form.querySelectorAll('button,textarea')],labels=controls.map(b=>b.textContent);form.dataset.answerBusy='true';form.setAttribute('aria-busy','true');controls.forEach(b=>b.disabled=true);form.querySelector('[role=status]').textContent='';const submitter=e.submitter;if(submitter)submitter.textContent=t('正在保存…','Saving…');const host=document.createElement('div');form.append(host);const progress=regenerate?generationProgress(host,t,{answer:true}):null;progress?.update('saving');let saved=false;try{
 await api('/api/question',{method:'PATCH',body:{id:q.id,action:'edit',baseBody:q.body,body:text},courseId:q.course_id,businessVersion:q.businessVersion});q.body=text.trim();saved=true;progress?.update('generating');if(submitter&&regenerate)submitter.textContent=t('AI 正在回答…','AI is answering…');
 let ai;if(regenerate)ai=(await api('/api/question/ai',{method:'POST',body:{id:q.id},courseId:q.course_id,businessVersion:q.businessVersion})).ai;
 if(form.isConnected)dialog('<h2>'+t('修改已保存','Changes saved')+'</h2><div class="message-markdown">'+markdown(q.body)+'</div>'+(regenerate?aiAnswerMarkup({...q,ai}):'<p>'+t('可在提问下点击“重新生成回答”。','Use “Regenerate answer” below the question when ready.')+'</p>'));
 if($('questionList'))await loadQuestions();
 }catch(error){if(form.isConnected)form.querySelector('[role=status]').textContent=(saved?t('修改已保存，回答未完成，可再次重试。','Changes saved; the answer did not finish. You can retry.')+' ':'')+error.message}finally{progress?.finish();host.remove();delete form.dataset.answerBusy;form.setAttribute('aria-busy','false');controls.forEach((b,i)=>{b.disabled=false;if(b.tagName==='BUTTON')b.textContent=labels[i]})}
 };
});
